/** Evidence-backed findings. Every finding names its source, method, scope and limitations. */
import { evidenceId, moduleEngine, type Brief, type CompetitorSnapshot, type Confidence, type EvidenceClass, type Finding, type FirstPartyData, type Module, type Severity } from "./model";
import type { Discovery } from "./crawl";
import type { PageRecord } from "./page";
import type { PerformanceResult } from "./psi";
import { geoReadiness, type SiteAnalysis } from "./site";

type Draft = {
  rule: string; module: Module; title: string; severity: Severity; summary: string;
  affected: { url: string; detail: string }[]; evidence: string[]; factors: string[];
  implication: string; recommendation: string; effort: Finding["effort"]; impact: Finding["impact"]; metric: string;
  confidence?: Confidence; evidenceClass?: EvidenceClass; source?: string; methodology?: string; limitations?: string[]; affectedCount?: number;
};

const crawlSource = "VisTa public crawl (retrieved HTML and HTTP responses)";
const crawlMethod = "Rule-based inspection of retrieved HTML, response headers and redirect chains for the crawled pages.";
const crawlLimits = ["Rendered JavaScript content is not executed.", "Only the crawled pages are assessed; the crawl may not cover the whole website."];

const share = (n: number, d: number) => (d ? Math.round(n / d * 100) + "%" : "n/a");
const list = (urls: string[], detail: string, max = 25) => urls.slice(0, max).map(url => ({ url, detail }));

export function buildFindings(projectId: string, brief: Brief, discovery: Discovery | null, pages: PageRecord[], site: SiteAnalysis, performance: PerformanceResult[], competitors: CompetitorSnapshot[], firstParty: FirstPartyData, collectedAt: string): Finding[] {
  const drafts: Draft[] = [];
  const indexable = pages.filter(p => p.indexable);
  const content = indexable.filter(p => !["legal", "contact"].includes(p.pageType));
  const n = pages.length;

  // Architecture and access.
  if (discovery?.robots.blocksAll) drafts.push({ rule: "robots-blocks-search", module: "indexability", title: "robots.txt blocks search engine crawlers from the home page", severity: "critical", summary: "The robots.txt rules disallow Googlebot from the site root.", affected: [{ url: discovery.robots.url, detail: "Disallow applies to /" }], evidence: ["robots.txt state: " + discovery.robots.state, "Googlebot root decision: disallowed"], factors: ["A staging or launch configuration may have been carried into production.", "A broad Disallow rule may be unintentional."], implication: "Search engines cannot crawl the site; new and updated content cannot earn organic visibility.", recommendation: "Remove or narrow the blocking Disallow rule and validate robots.txt in Search Console.", effort: "low", impact: 5, metric: "Googlebot allowed on priority URLs; indexed page count in Search Console." });
  if (discovery?.robots.state === "unavailable") drafts.push({ rule: "robots-unavailable", module: "indexability", title: "robots.txt returns a server error", severity: "high", summary: "robots.txt could not be retrieved (server error or network failure).", affected: [{ url: discovery.robots.url, detail: "Status " + (discovery.robots.status ?? "no response") }], evidence: ["Under RFC 9309 crawlers treat an unreachable robots.txt as a full disallow."], factors: ["Server or CDN misconfiguration for /robots.txt."], implication: "Search engines may pause crawling the whole site until robots.txt is reachable.", recommendation: "Serve robots.txt with HTTP 200 (or 404 if intentionally absent).", effort: "low", impact: 5, metric: "robots.txt returns HTTP 200." });
  if (discovery && discovery.robots.blocksVista && !discovery.robots.blocksAll) drafts.push({ rule: "crawler-restricted", module: "architecture", title: "The website restricts automated crawlers like VisTa", severity: "info", summary: "robots.txt disallows the VisTa crawler, which was respected. Coverage of this assessment is limited.", affected: [{ url: discovery.robots.url, detail: "Restricted for VistaSiteIntelligence" }], evidence: [site.robotsBlocked.length + " URLs skipped because of robots.txt."], factors: ["Bot management or restrictive default rules."], implication: "Findings reflect only the pages VisTa was permitted to inspect.", recommendation: "If you control the site, allow VisTa for the audit window or supply authorised Search Console data.", effort: "low", impact: 1, metric: "Crawl coverage of priority templates.", confidence: "high" });
  if (discovery && !discovery.sitemaps.some(s => s.kind === "urlset" || s.kind === "index")) drafts.push({ rule: "sitemap-missing", module: "architecture", title: "No valid XML sitemap was found", severity: "medium", summary: "Neither robots.txt nor the default locations provided a parseable XML sitemap.", affected: discovery.sitemaps.length ? discovery.sitemaps.map(s => ({ url: s.url, detail: s.error || s.kind })) : [{ url: discovery.origin + "/sitemap.xml", detail: "Not found" }], evidence: ["Sitemaps declared in robots.txt: " + discovery.robots.sitemaps.length], factors: ["The CMS sitemap feature may be disabled or the sitemap is not declared in robots.txt."], implication: "Search engines rely on links alone to find pages, slowing discovery of new or deep content.", recommendation: "Publish an XML sitemap of canonical, indexable URLs and declare it in robots.txt and Search Console.", effort: "low", impact: 3, metric: "Valid sitemap submitted; submitted vs indexed counts in Search Console." });
  else if (discovery?.sitemaps.some(s => s.kind === "invalid" || s.kind === "unreachable")) drafts.push({ rule: "sitemap-errors", module: "architecture", title: "Some declared sitemaps cannot be read", severity: "medium", summary: "One or more sitemap URLs failed or are not valid sitemap XML.", affected: discovery.sitemaps.filter(s => s.kind === "invalid" || s.kind === "unreachable").map(s => ({ url: s.url, detail: s.error || s.kind })), evidence: discovery.sitemaps.map(s => s.url + ": " + s.kind + " (" + s.entries + " entries)"), factors: ["Stale sitemap references after a migration."], implication: "Pages listed only in the failing sitemaps are discovered more slowly.", recommendation: "Remove dead sitemap references and fix XML errors.", effort: "low", impact: 2, metric: "All declared sitemaps return valid XML." });

  if (site.brokenInternal.length) drafts.push({ rule: "broken-internal-links", module: "architecture", title: site.brokenInternal.length + " broken internal links", severity: site.brokenInternal.length > 10 ? "high" : "medium", summary: "Internal links point to URLs that return errors.", affected: site.brokenInternal.slice(0, 30).map(b => ({ url: b.source, detail: "→ " + b.target + " (" + (b.status ?? b.reason) + ")" })), affectedCount: site.brokenInternal.length, evidence: [new Set(site.brokenInternal.map(b => b.target)).size + " unique failing destinations", "Status codes: " + [...new Set(site.brokenInternal.map(b => String(b.status ?? "no response")))].join(", ")], factors: ["Deleted or renamed pages without redirects.", "Hard-coded links in templates or navigation."], implication: "Visitors hit dead ends and crawl budget is spent on errors; link equity is lost.", recommendation: "Update links to live destinations or add 301 redirects for removed pages.", effort: "low", impact: 4, metric: "Zero internal links to 4xx/5xx URLs in the next crawl." });
  if (site.brokenExternal.length) drafts.push({ rule: "broken-external-links", module: "authority", title: site.brokenExternal.length + " broken outbound links", severity: "low", summary: "Outbound links to other websites return errors.", affected: site.brokenExternal.slice(0, 30).map(b => ({ url: b.source, detail: "→ " + b.target + " (" + (b.status ?? b.reason) + ")" })), affectedCount: site.brokenExternal.length, evidence: ["Checked within the configured external link budget; 403/429 responses excluded as possible bot blocking."], factors: ["Referenced sources moved or expired."], implication: "Dead citations weaken perceived quality and the credibility of claims.", recommendation: "Replace or remove dead references.", effort: "low", impact: 2, metric: "Zero broken outbound links." });
  const loops = site.redirects.filter(r => r.loop);
  if (loops.length) drafts.push({ rule: "redirect-loops", module: "architecture", title: loops.length + " redirect loops", severity: "high", summary: "Some URLs redirect in a loop and never resolve.", affected: loops.map(r => ({ url: r.url, detail: r.chain.map(h => h.status).join(" → ") })), evidence: loops.map(r => r.chain.map(h => h.url).join(" → ")).slice(0, 5), factors: ["Conflicting redirect rules (for example trailing-slash and HTTPS rules)."], implication: "These URLs are inaccessible to users and search engines.", recommendation: "Resolve the conflicting rules so each URL reaches one final 200 page.", effort: "medium", impact: 4, metric: "No redirect loops in crawl." });
  const chains = site.redirects.filter(r => !r.loop && r.chain.length > 2);
  if (chains.length) drafts.push({ rule: "redirect-chains", module: "architecture", title: chains.length + " multi-hop redirect chains", severity: "medium", summary: "URLs reach their destination only after two or more redirects.", affected: chains.slice(0, 25).map(r => ({ url: r.url, detail: r.chain.map(h => h.status).join(" → ") + " → " + (r.chain.at(-1)?.url || "") })), evidence: ["Longest chain: " + Math.max(...chains.map(c => c.chain.length - 1)) + " hops"], factors: ["Layered migrations (HTTP→HTTPS→www→trailing slash)."], implication: "Each hop adds latency and dilutes signals passed through links.", recommendation: "Redirect directly to the final URL and update internal links.", effort: "low", impact: 2, metric: "All redirects resolve in one hop." });
  if (site.internalRedirectLinks.length) drafts.push({ rule: "internal-links-to-redirects", module: "architecture", title: site.internalRedirectLinks.length + " internal links point to redirecting URLs", severity: "low", summary: "Navigation and content link to URLs that redirect rather than to final addresses.", affected: site.internalRedirectLinks.slice(0, 25).map(l => ({ url: l.source, detail: l.target + " → " + l.finalUrl })), affectedCount: site.internalRedirectLinks.length, evidence: [new Set(site.internalRedirectLinks.map(l => l.target)).size + " unique redirecting targets"], factors: ["Links not updated after URL changes."], implication: "Unnecessary redirects slow navigation and waste crawl resources.", recommendation: "Update internal links to the final destination URLs.", effort: "low", impact: 2, metric: "Internal links resolve without redirects." });
  const deep = pages.filter(p => p.depth > 3);
  if (deep.length) drafts.push({ rule: "deep-pages", module: "architecture", title: deep.length + " pages are more than three clicks from the home page", severity: deep.some(p => ["product", "service", "course", "category"].includes(p.pageType)) ? "medium" : "low", summary: "Important content is buried deep in the link structure.", affected: deep.slice(0, 25).map(p => ({ url: p.finalUrl, detail: "Depth " + p.depth + " · " + p.pageType })), affectedCount: deep.length, evidence: ["Depth distribution: " + site.depth.map(d => d.depth + ":" + d.count).join(", ")], factors: ["Pagination or nested category paths without cross-links."], implication: "Deep pages are crawled less often and receive less internal authority.", recommendation: "Add contextual and hub links so priority pages are within three clicks.", effort: "medium", impact: 3, metric: "Priority pages at depth ≤ 3." });
  if (site.orphans.state === "assessed" && site.orphans.urls.length) drafts.push({ rule: "orphan-pages", module: "architecture", title: site.orphans.urls.length + " sitemap URLs are not linked from crawled pages", severity: "medium", summary: "Pages exist in the sitemap but no crawled page links to them.", affected: list(site.orphans.urls, "In sitemap; no internal link observed"), affectedCount: site.orphans.urls.length, evidence: [site.orphans.reason], factors: ["Pages removed from navigation but left published.", "Campaign landing pages without hub links."], implication: "Orphaned pages are hard for users and search engines to discover and rarely rank.", recommendation: "Link valuable orphan pages from relevant hubs, or remove/noindex obsolete ones.", effort: "medium", impact: 3, metric: "Orphan count in subsequent crawls.", confidence: "medium" });
  if (site.parameterUrls.length > 5) drafts.push({ rule: "parameter-urls", module: "indexability", title: site.parameterUrls.length + " internally linked URLs carry query parameters", severity: "low", summary: "Parameterised URLs can create duplicate crawl paths.", affected: list(site.parameterUrls, "Parameter URL linked internally"), evidence: ["Parameters: " + [...new Set(site.parameterUrls.flatMap(u => [...new URL(u).searchParams.keys()]))].slice(0, 12).join(", ")], factors: ["Faceted navigation, tracking or sort parameters in links."], implication: "Duplicate URL variants can dilute signals and waste crawl budget.", recommendation: "Canonicalise parameter variants, avoid linking tracking parameters internally, and restrict crawlable facets.", effort: "medium", impact: 2, metric: "Parameterised URLs canonicalised or excluded." });

  // Indexability.
  if (site.indexability.nonIndexable) drafts.push({ rule: "non-indexable-pages", module: "indexability", title: site.indexability.nonIndexable + " crawled pages are not technically indexable", severity: pages.filter(p => !p.indexable && ["product", "service", "category", "course", "home"].includes(p.pageType)).length ? "high" : "medium", summary: "Pages carry noindex, point their canonical elsewhere or resolve through redirects.", affected: pages.filter(p => !p.indexable).slice(0, 30).map(p => ({ url: p.url, detail: p.indexReasons.join(" ") })), affectedCount: site.indexability.nonIndexable, evidence: Object.entries(site.indexability.reasons).map(([r, c]) => r + ": " + c), factors: ["Template-level robots or canonical settings.", "Migration redirects."], implication: "Non-indexable commercial pages cannot appear in search results. Technical indexability is not confirmed indexing; Search Console evidence is needed for that.", recommendation: "Confirm each exclusion is intentional; remove noindex or fix canonicals on pages that should rank.", effort: "low", impact: 4, metric: "Indexable status of priority templates; Search Console indexed count.", limitations: [...crawlLimits, "Technical indexability does not prove a page is or is not in Google's index."] });
  const homeUrl = (discovery?.home?.finalUrl || pages.find(p => p.depth === 0)?.finalUrl || "").replace(/\/$/, "");
  const toHome = homeUrl ? pages.filter(p => p.depth !== 0 && p.canonical && p.canonical.replace(/\/$/, "") === homeUrl && p.finalUrl.replace(/\/$/, "") !== homeUrl) : [];
  if (toHome.length >= 2) drafts.push({ rule: "canonical-to-home", module: "indexability", title: toHome.length + " inner pages declare the home page as their canonical URL", severity: "high", summary: "Distinct pages tell search engines that the home page is the preferred version of their content.", affected: toHome.slice(0, 30).map(p => ({ url: p.finalUrl, detail: "rel=canonical → " + p.canonical })), affectedCount: toHome.length, evidence: [toHome.length + " of " + (pages.length - 1) + " crawled inner pages", "Declared in the server-delivered HTML."], factors: ["A site-wide template or single-page application sets one static canonical for every route."], implication: "Search engines may consolidate these pages into the home page, so service, product or project pages may not appear in search results.", recommendation: "Emit a self-referencing canonical per page in the server-rendered HTML, then confirm the Google-selected canonical in Search Console URL Inspection.", effort: "low", impact: 5, metric: "Self-referencing canonicals on inner pages; inner pages indexed in Search Console.", limitations: [...crawlLimits, "If JavaScript updates the canonical after rendering, search engines that render may see a different value; URL Inspection confirms the selected canonical."] });
  if (site.canonicalIssues.length) drafts.push({ rule: "canonical-conflicts", module: "indexability", title: site.canonicalIssues.length + " canonical conflicts", severity: "high", summary: "Canonical tags point to error, redirecting, noindexed or external URLs.", affected: site.canonicalIssues.slice(0, 25).map(c => ({ url: c.url, detail: c.problem + " (" + c.canonical + ")" })), evidence: [...new Set(site.canonicalIssues.map(c => c.problem))].slice(0, 6), factors: ["Hard-coded canonicals after URL changes."], implication: "Conflicting signals can cause search engines to ignore the canonical or index the wrong URL.", recommendation: "Point each canonical to the live, indexable, final URL.", effort: "low", impact: 4, metric: "Zero canonical conflicts." });
  const missingCanonical = indexable.filter(p => !p.canonical);
  if (missingCanonical.length > n * 0.3) drafts.push({ rule: "canonical-missing", module: "indexability", title: "Canonical tags are missing on " + share(missingCanonical.length, n) + " of pages", severity: "low", summary: "Without canonicals, duplicate URL variants rely on search-engine selection.", affected: list(missingCanonical.map(p => p.finalUrl), "No rel=canonical"), affectedCount: missingCanonical.length, evidence: [missingCanonical.length + " of " + n + " pages"], factors: ["CMS default templates."], implication: "Parameter or trailing-slash variants may compete with preferred URLs.", recommendation: "Add self-referencing canonicals to indexable templates.", effort: "low", impact: 2, metric: "Canonical coverage of indexable pages." });
  if (site.sitemapIssues.length) drafts.push({ rule: "sitemap-conflicts", module: "indexability", title: site.sitemapIssues.length + " sitemap URLs conflict with page signals", severity: "medium", summary: "The sitemap lists URLs that redirect, error, are noindexed or canonicalised elsewhere.", affected: site.sitemapIssues.slice(0, 25).map(s => ({ url: s.url, detail: s.problem })), evidence: [...new Set(site.sitemapIssues.map(s => s.problem.replace(/ to .*| HTTP \d+.*/, "")))], factors: ["Sitemap generation includes non-canonical URLs."], implication: "Mixed signals reduce trust in the sitemap as a canonical inventory.", recommendation: "List only canonical, indexable 200 URLs in sitemaps.", effort: "low", impact: 3, metric: "Sitemap contains only canonical 200 URLs." });
  if (site.hreflangIssues.length) drafts.push({ rule: "hreflang-issues", module: "indexability", title: site.hreflangIssues.length + " international targeting (hreflang) issues", severity: "medium", summary: "hreflang annotations are invalid, missing self-references or not reciprocal.", affected: site.hreflangIssues.slice(0, 25).map(h => ({ url: h.url, detail: h.problem })), evidence: [...new Set(site.hreflangIssues.map(h => h.problem.replace(/".*"|https?:\S+/g, "…")))].slice(0, 5), factors: ["Partial implementation across locales."], implication: "Search engines may show the wrong language or regional version to users.", recommendation: "Ensure each locale lists all alternates including itself, reciprocally, with valid codes.", effort: "medium", impact: 3, metric: "Valid reciprocal hreflang clusters." });

  // On-page.
  const noTitle = pages.filter(p => !p.title);
  if (noTitle.length) drafts.push({ rule: "missing-titles", module: "on-page", title: noTitle.length + " pages without a title", severity: "high", summary: "Pages have no HTML title element.", affected: list(noTitle.map(p => p.finalUrl), "No <title>"), evidence: [share(noTitle.length, n) + " of crawled pages"], factors: ["Template omission."], implication: "Search results show an auto-generated title, reducing relevance and click-through.", recommendation: "Write unique, descriptive titles reflecting each page's search intent.", effort: "low", impact: 4, metric: "Title coverage 100%." });
  const titleLength = pages.filter(p => p.title && (p.title.length < 30 || p.title.length > 65));
  if (titleLength.length > Math.max(1, n * 0.2)) drafts.push({ rule: "title-length", module: "on-page", title: titleLength.length + " titles are too short or likely truncated", severity: "low", summary: "Titles fall outside the 30–65 character range commonly displayed in full.", affected: titleLength.slice(0, 25).map(p => ({ url: p.finalUrl, detail: p.title!.length + " chars: " + p.title!.slice(0, 80) })), affectedCount: titleLength.length, evidence: ["Character count is a proxy; actual display depends on pixel width."], factors: ["Brand suffixes or terse templates."], implication: "Truncated or vague titles can reduce click-through from search results.", recommendation: "Lead with the primary topic and keep titles concise.", effort: "low", impact: 2, metric: "Share of titles within range.", confidence: "medium" });
  const noDescription = indexable.filter(p => !p.description);
  if (noDescription.length) drafts.push({ rule: "missing-descriptions", module: "on-page", title: noDescription.length + " indexable pages lack a meta description", severity: "medium", summary: "No meta description is declared.", affected: list(noDescription.map(p => p.finalUrl), "No meta description"), affectedCount: noDescription.length, evidence: [share(noDescription.length, indexable.length) + " of indexable pages"], factors: ["Descriptions not required in the CMS."], implication: "Search engines generate snippets that may not express the value proposition.", recommendation: "Write specific descriptions that answer the searcher's intent and include a reason to click.", effort: "low", impact: 2, metric: "Description coverage; CTR for affected pages in Search Console." });
  if (site.duplicateTitles.length) drafts.push({ rule: "duplicate-titles", module: "on-page", title: site.duplicateTitles.reduce((s, d) => s + d.urls.length, 0) + " pages share duplicate titles", severity: "medium", summary: site.duplicateTitles.length + " title values are reused across distinct indexable pages.", affected: site.duplicateTitles.slice(0, 10).flatMap(d => d.urls.slice(0, 5).map(url => ({ url, detail: "\"" + d.value.slice(0, 80) + "\"" }))), evidence: site.duplicateTitles.slice(0, 5).map(d => d.urls.length + "× \"" + d.value.slice(0, 70) + "\""), factors: ["Templated titles without page-specific variables."], implication: "Duplicate titles make pages compete for the same queries (cannibalisation risk) and reduce relevance.", recommendation: "Give each page a unique title aligned with its distinct intent.", effort: "low", impact: 3, metric: "Duplicate title groups." });
  if (site.duplicateDescriptions.length) drafts.push({ rule: "duplicate-descriptions", module: "on-page", title: site.duplicateDescriptions.length + " meta descriptions are reused", severity: "low", summary: "The same description appears on multiple indexable pages.", affected: site.duplicateDescriptions.slice(0, 10).flatMap(d => d.urls.slice(0, 4).map(url => ({ url, detail: "\"" + d.value.slice(0, 80) + "\"" }))), evidence: site.duplicateDescriptions.slice(0, 4).map(d => d.urls.length + " pages"), factors: ["Site-wide default description."], implication: "Generic snippets weaken differentiation in search results.", recommendation: "Write page-specific descriptions.", effort: "low", impact: 1, metric: "Duplicate description groups." });
  if (site.nearDuplicates.length) drafts.push({ rule: "near-duplicate-content", module: "content", title: site.nearDuplicates.length + " near-duplicate page pairs", severity: "medium", summary: "Pages share at least 85% of their textual shingles.", affected: site.nearDuplicates.slice(0, 20).map(d => ({ url: d.a, detail: Math.round(d.similarity * 100) + "% similar to " + d.b })), evidence: ["MinHash similarity over five-word shingles of visible text."], factors: ["Location or variant pages generated from one template.", "Syndicated or copied copy."], implication: "Search engines may filter duplicates and choose a different URL to rank.", recommendation: "Consolidate, differentiate with unique substance, or canonicalise variants.", effort: "medium", impact: 3, metric: "Near-duplicate pairs.", confidence: "medium", methodology: "MinHash (32 permutations) of five-word shingles; ≥ 0.85 estimated Jaccard similarity." });
  const h1Issues = pages.filter(p => p.h1.length !== 1);
  if (h1Issues.length > Math.max(1, n * 0.15)) drafts.push({ rule: "h1-issues", module: "on-page", title: h1Issues.length + " pages lack a single clear H1", severity: "medium", summary: "Pages have no H1 or several H1 headings.", affected: h1Issues.slice(0, 25).map(p => ({ url: p.finalUrl, detail: p.h1.length + " H1" })), affectedCount: h1Issues.length, evidence: ["Without H1: " + pages.filter(p => !p.h1.length).length, "Multiple H1: " + pages.filter(p => p.h1.length > 1).length], factors: ["Logo or hero markup using H1."], implication: "Unclear primary headings weaken topical signals and accessibility.", recommendation: "Use one descriptive H1 per page.", effort: "low", impact: 2, metric: "Pages with exactly one H1." });
  const hierarchy = pages.filter(p => p.headingIssues.some(i => i.startsWith("Heading level skips")));
  if (hierarchy.length > Math.max(2, n * 0.25)) drafts.push({ rule: "heading-hierarchy", module: "accessibility", title: hierarchy.length + " pages skip heading levels", severity: "low", summary: "Heading levels jump (for example H2 to H4).", affected: hierarchy.slice(0, 20).map(p => ({ url: p.finalUrl, detail: p.headingIssues.find(i => i.startsWith("Heading"))! })), evidence: ["Detected from DOM order of H1–H6."], factors: ["Headings chosen for visual size rather than structure."], implication: "Screen-reader navigation and content structure clarity suffer.", recommendation: "Use headings in sequential order and style them with CSS.", effort: "low", impact: 1, metric: "Pages with sequential headings." });
  const thin = content.filter(p => p.content.words < 250 && !["home", "category"].includes(p.pageType));
  if (thin.length) drafts.push({ rule: "thin-content", module: "content", title: thin.length + " indexable pages have thin content", severity: thin.length > n * 0.3 ? "medium" : "low", summary: "Pages contain fewer than 250 words of visible text.", affected: thin.slice(0, 25).map(p => ({ url: p.finalUrl, detail: p.content.words + " words · " + p.pageType })), affectedCount: thin.length, evidence: ["Median words on content pages: " + median(content.map(p => p.content.words))], factors: ["Placeholder or image-led pages.", "Content rendered by JavaScript (not visible in retrieved HTML)."], implication: "Thin pages rarely satisfy search intent or get cited by AI answers.", recommendation: "Expand with substantive, original information or consolidate pages.", effort: "medium", impact: 3, metric: "Words and engagement on affected pages.", confidence: "medium" });
  const kw = brief.keywords.filter(Boolean);
  if (kw.length && pages.length) {
    const absent = kw.filter(k => !pages.some(p => p.keywords.find(x => x.keyword === k.toLowerCase())?.inTitle || p.keywords.find(x => x.keyword === k.toLowerCase())?.inH1));
    if (absent.length) drafts.push({ rule: "keyword-gaps", module: "on-page", title: absent.length + " target keywords have no focused page", severity: "high", summary: "No crawled page uses these target keywords in its title or H1.", affected: absent.map(k => ({ url: brief.website, detail: "Keyword: " + k })), evidence: absent.map(k => "\"" + k + "\": " + pages.filter(p => (p.keywords.find(x => x.keyword === k.toLowerCase())?.bodyCount || 0) > 0).length + " pages mention it in body text"), factors: ["Content strategy not mapped to target demand."], implication: "Without a focused landing page, the site is unlikely to rank or be cited for these commercial topics.", recommendation: "Create or optimise one dedicated page per target keyword theme with matching title, H1 and content.", effort: "medium", impact: 4, metric: "Rankings and impressions for target keywords (Search Console).", confidence: "medium" });
    const cannibal = kw.map(k => ({ k, urls: pages.filter(p => p.keywords.find(x => x.keyword === k.toLowerCase())?.inTitle).map(p => p.finalUrl) })).filter(x => x.urls.length > 1);
    if (cannibal.length) drafts.push({ rule: "keyword-cannibalisation", module: "on-page", title: cannibal.length + " keywords are targeted by several page titles", severity: "medium", summary: "Multiple pages place the same target keyword in their title.", affected: cannibal.flatMap(c => c.urls.slice(0, 6).map(url => ({ url, detail: "Keyword: " + c.k }))), evidence: cannibal.map(c => "\"" + c.k + "\": " + c.urls.length + " pages"), factors: ["Overlapping articles and service pages."], implication: "Pages may compete for the same query, splitting relevance and links.", recommendation: "Choose one primary page per keyword; differentiate or consolidate the others.", effort: "medium", impact: 3, metric: "Single ranking URL per target query (Search Console page/query data).", confidence: "medium", methodology: "Title-level overlap only. Confirm with Search Console query-to-page data." });
  }

  // Images and media.
  const imagesMissing = pages.reduce((s, p) => s + p.images.missingAlt, 0);
  const imagesTotal = pages.reduce((s, p) => s + p.images.count, 0);
  if (imagesMissing) drafts.push({ rule: "image-alt", module: "accessibility", title: imagesMissing + " images lack alternative text", severity: imagesMissing / Math.max(1, imagesTotal) > 0.3 ? "medium" : "low", summary: "Images have no alt attribute (empty alt for decorative images is acceptable and excluded).", affected: pages.filter(p => p.images.missingAlt).slice(0, 25).map(p => ({ url: p.finalUrl, detail: p.images.missingAlt + " of " + p.images.count + " images" })), evidence: [share(imagesMissing, imagesTotal) + " of " + imagesTotal + " images"], factors: ["Editors not prompted for alt text."], implication: "Excludes screen-reader users and removes image search relevance.", recommendation: "Add meaningful alt text to informative images; use alt=\"\" for decorative ones.", effort: "low", impact: 2, metric: "Images with alt attributes." });
  const legacy = pages.reduce((s, p) => s + p.images.legacyFormat, 0);
  const noDims = pages.reduce((s, p) => s + p.images.noDimensions, 0);
  if (legacy > 10 || noDims > 10) drafts.push({ rule: "image-optimisation", module: "performance", title: "Image delivery can be optimised", severity: "low", summary: legacy + " images use legacy formats without modern alternatives; " + noDims + " lack explicit dimensions.", affected: pages.filter(p => p.images.legacyFormat || p.images.noDimensions).slice(0, 20).map(p => ({ url: p.finalUrl, detail: p.images.legacyFormat + " legacy · " + p.images.noDimensions + " without width/height" })), evidence: ["Detected from image source extensions and attributes in HTML; byte sizes not measured."], factors: ["No image CDN or responsive image pipeline."], implication: "Heavier images slow loading; missing dimensions cause layout shift.", recommendation: "Serve WebP/AVIF with responsive sizes and set width/height attributes.", effort: "medium", impact: 2, metric: "LCP and CLS (field data).", confidence: "medium" });

  // Structured data and entity.
  const noSchema = indexable.filter(p => !p.schema.types.length);
  if (noSchema.length > n * 0.5) drafts.push({ rule: "structured-data-gaps", module: "authority", title: "Structured data is missing on " + share(noSchema.length, indexable.length) + " of indexable pages", severity: "medium", summary: "No typed JSON-LD was found on most pages.", affected: list(noSchema.map(p => p.finalUrl), "No JSON-LD types"), affectedCount: noSchema.length, evidence: ["Types found elsewhere: " + ([...new Set(pages.flatMap(p => p.schema.types))].slice(0, 12).join(", ") || "none")], factors: ["Schema not configured in the CMS or theme."], implication: "Search engines and AI systems have less explicit understanding of entities, products and content.", recommendation: "Implement accurate Organization, BreadcrumbList and page-type schema (Product, Service, Course, Article, FAQ where genuine).", effort: "medium", impact: 3, metric: "Valid structured data coverage (Rich Results Test, Search Console enhancements)." });
  const schemaErrors = pages.filter(p => p.schema.errors);
  if (schemaErrors.length) drafts.push({ rule: "structured-data-errors", module: "authority", title: schemaErrors.length + " pages contain invalid JSON-LD", severity: "medium", summary: "JSON-LD blocks could not be parsed.", affected: schemaErrors.slice(0, 20).map(p => ({ url: p.finalUrl, detail: p.schema.errors + " unparseable block(s)" })), evidence: ["JSON syntax errors prevent any use of the markup."], factors: ["Manual editing or template escaping errors."], implication: "Broken markup is ignored, losing eligibility for rich results.", recommendation: "Fix the JSON syntax and validate with the Rich Results Test.", effort: "low", impact: 2, metric: "Zero JSON-LD parse errors." });
  if (pages.length && !pages.some(p => p.schema.organisation)) drafts.push({ rule: "organisation-entity", module: "authority", title: "No Organization entity is declared", severity: "medium", summary: "No page declares Organization (or LocalBusiness) structured data.", affected: [{ url: brief.website, detail: "No Organization JSON-LD" }], evidence: ["Checked " + n + " pages."], factors: ["Entity markup not implemented."], implication: "Weaker entity clarity for knowledge panels and AI systems describing the brand.", recommendation: "Declare an Organization entity with legal name, logo, contact points and sameAs links to official profiles.", effort: "low", impact: 3, metric: "Organization entity present and consistent." });
  else { const org = pages.find(p => p.schema.organisation)?.schema.organisation; if (org && org.sameAs.length < 2) drafts.push({ rule: "entity-sameas", module: "authority", title: "Organisation entity has few verified profile links", severity: "low", summary: "The Organization entity lists " + org.sameAs.length + " sameAs profiles.", affected: [{ url: brief.website, detail: "sameAs: " + (org.sameAs.join(", ") || "none") }], evidence: ["Declared name: " + (org.name || "not declared")], factors: ["Profiles not connected to the entity."], implication: "AI systems and search engines have fewer corroborating identity sources.", recommendation: "Add sameAs links to official profiles (LinkedIn, Wikidata, Crunchbase, industry registries).", effort: "low", impact: 2, metric: "Corroborating profiles linked.", confidence: "medium" }); }

  // Trust and security.
  const http = pages.filter(p => !p.trust.https);
  if (http.length) drafts.push({ rule: "https", module: "trust", title: http.length + " pages served without HTTPS", severity: "critical", summary: "Pages are reachable over unencrypted HTTP without redirecting to HTTPS.", affected: list(http.map(p => p.finalUrl), "HTTP"), evidence: [share(http.length, n)], factors: ["Missing HTTPS redirect."], implication: "Browsers flag the site as not secure; trust and rankings suffer.", recommendation: "Redirect all HTTP traffic to HTTPS and enable HSTS.", effort: "low", impact: 5, metric: "All pages HTTPS." });
  const mixed = pages.filter(p => p.trust.mixedContent.length);
  if (mixed.length) drafts.push({ rule: "mixed-content", module: "trust", title: mixed.length + " HTTPS pages load insecure resources", severity: "high", summary: "HTTP resources are referenced from HTTPS pages.", affected: mixed.slice(0, 20).map(p => ({ url: p.finalUrl, detail: p.trust.mixedContent.slice(0, 3).join(", ") })), evidence: ["Detected from src/href attributes in HTML."], factors: ["Hard-coded http:// asset URLs."], implication: "Browsers block or warn on insecure content; padlock and trust are affected.", recommendation: "Serve all assets over HTTPS.", effort: "low", impact: 3, metric: "Zero mixed-content references." });
  const home = pages.find(p => p.depth === 0) || pages[0];
  if (home && home.trust.https && !home.trust.hsts) drafts.push({ rule: "hsts", module: "trust", title: "HSTS is not enabled", severity: "low", summary: "The home page response has no Strict-Transport-Security header.", affected: [{ url: home.finalUrl, detail: "No HSTS header" }], evidence: ["Security headers observed: " + ["csp", "contentTypeOptions"].filter(k => home.trust[k as "csp"]).join(", ")], factors: ["Header not configured at the server or CDN."], implication: "Users can be downgraded to HTTP on first visit.", recommendation: "Enable HSTS with an appropriate max-age after confirming full HTTPS coverage.", effort: "low", impact: 1, metric: "HSTS header present." });
  if (home) {
    const missing = [["Contact", home.trust.contactLink || pages.some(p => p.pageType === "contact")], ["About", home.trust.aboutLink || pages.some(p => p.pageType === "about")], ["Privacy policy", home.trust.privacyLink || pages.some(p => p.pageType === "legal")], ["Terms", home.trust.termsLink], ["Telephone or address", pages.some(p => p.trust.telephone || p.trust.address)]].filter(([, ok]) => !ok).map(([label]) => label as string);
    if (missing.length) drafts.push({ rule: "trust-signals", module: "trust", title: "Business identity signals are incomplete", severity: missing.length >= 3 ? "high" : "medium", summary: "Missing or not linked: " + missing.join(", ") + ".", affected: [{ url: home.finalUrl, detail: missing.join(", ") }], evidence: ["Checked home page links and crawled page types."], factors: ["Footer navigation omits trust pages."], implication: "Visitors, search quality raters and AI systems look for verifiable business identity before trusting claims.", recommendation: "Link contact, about, privacy and terms pages site-wide and publish verifiable contact details.", effort: "low", impact: 3, metric: "Trust links present site-wide." });
  }
  const articles = pages.filter(p => p.pageType === "article");
  const anonymous = articles.filter(p => !p.trust.authorSignal);
  if (articles.length >= 3 && anonymous.length > articles.length * 0.5) drafts.push({ rule: "author-expertise", module: "trust", title: anonymous.length + " articles show no author information", severity: "medium", summary: "Editorial content lacks visible or structured author attribution.", affected: list(anonymous.map(p => p.finalUrl), "No author signal"), evidence: [anonymous.length + " of " + articles.length + " articles"], factors: ["Content published under a generic account."], implication: "Expertise cannot be demonstrated, weakening E-E-A-T and AI citation likelihood.", recommendation: "Attribute articles to named experts with bios and Person schema.", effort: "low", impact: 3, metric: "Articles with author attribution." });
  const stale = articles.filter(p => { const d = Date.parse(p.dates?.modified || p.dates?.published || ""); return Number.isFinite(d) && Date.now() - d > 540 * 86400000; });
  if (stale.length >= 2) drafts.push({ rule: "content-freshness", module: "content", title: stale.length + " articles not updated for over 18 months", severity: "low", summary: "Declared modified/published dates are older than 18 months.", affected: stale.slice(0, 20).map(p => ({ url: p.finalUrl, detail: (p.dates?.modified || p.dates?.published || "") + " (" + p.dates?.source + ")" })), evidence: ["Only pages with verifiable dates are assessed."], factors: ["No content review cycle."], implication: "Outdated content loses relevance and is less likely to be cited for current questions.", recommendation: "Review, update and re-date high-value articles; retire obsolete ones.", effort: "medium", impact: 2, metric: "Share of articles reviewed within 12 months.", confidence: "medium" });

  // Accessibility basics.
  const a11y = pages.filter(p => p.accessibility.unlabelledInputs || p.accessibility.unnamedButtons || !p.accessibility.langDeclared || p.accessibility.emptyLinks > 2);
  if (a11y.length) drafts.push({ rule: "accessibility-basics", module: "accessibility", title: a11y.length + " pages have basic accessibility issues", severity: a11y.some(p => p.accessibility.unlabelledInputs) ? "medium" : "low", summary: "Unlabelled form fields, unnamed buttons, empty links or missing language declarations.", affected: a11y.slice(0, 25).map(p => ({ url: p.finalUrl, detail: [p.accessibility.unlabelledInputs && p.accessibility.unlabelledInputs + " unlabelled fields", p.accessibility.unnamedButtons && p.accessibility.unnamedButtons + " unnamed buttons", p.accessibility.emptyLinks > 2 && p.accessibility.emptyLinks + " empty links", !p.accessibility.langDeclared && "no lang"].filter(Boolean).join(", ") })), evidence: ["Static HTML checks only; contrast, keyboard behaviour and assistive technology testing are not covered."], factors: ["Components without accessible names."], implication: "Users of assistive technology may be unable to complete enquiries or purchases; legal accessibility obligations may apply.", recommendation: "Label every field, name every control, declare the page language and test with assistive technology.", effort: "medium", impact: 3, metric: "Automated accessibility issues per page.", limitations: ["Basic static checks; not a WCAG conformance audit."] });
  if (home && !home.viewport) drafts.push({ rule: "mobile-viewport", module: "performance", title: "Mobile viewport is not configured", severity: "high", summary: "The home page has no responsive width=device-width viewport.", affected: [{ url: home.finalUrl, detail: "No responsive viewport" }], evidence: ["Meta viewport missing or fixed-width."], factors: ["Legacy desktop template."], implication: "Mobile users see a zoomed-out desktop page; mobile-first indexing is affected.", recommendation: "Declare a responsive viewport and ensure layouts adapt.", effort: "medium", impact: 4, metric: "Mobile usability." });

  // Performance (HTML indicators and PageSpeed).
  const blocking = pages.filter(p => p.performance.renderBlockingScripts >= 3);
  if (blocking.length > n * 0.3) drafts.push({ rule: "render-blocking-html", module: "performance", title: "Render-blocking scripts in the document head", severity: "medium", summary: blocking.length + " pages load three or more synchronous scripts before rendering.", affected: blocking.slice(0, 20).map(p => ({ url: p.finalUrl, detail: p.performance.renderBlockingScripts + " blocking scripts · " + p.performance.thirdPartyHosts.length + " third-party hosts" })), evidence: ["Detected from script tags without async/defer/module in <head>."], factors: ["Tag managers and widgets loaded synchronously."], implication: "Delays first render and Largest Contentful Paint, especially on mobile.", recommendation: "Defer non-critical scripts and audit third-party tags.", effort: "medium", impact: 3, metric: "LCP field percentile; render-blocking count.", confidence: "medium" });
  for (const result of performance.filter(r => r.strategy === "mobile")) {
    const poor = [result.field.lcp?.category === "SLOW" && "LCP " + Math.round(result.field.lcp.percentile) + " ms", result.field.inp?.category === "SLOW" && "INP " + Math.round(result.field.inp.percentile) + " ms", result.field.cls?.category === "SLOW" && "CLS " + result.field.cls.percentile.toFixed(2)].filter(Boolean) as string[];
    if (poor.length) drafts.push({ rule: "cwv-field-poor:" + result.url, module: "performance", title: "Real-user Core Web Vitals are poor on mobile", severity: "high", summary: "Chrome UX Report 75th-percentile field data is in the poor range: " + poor.join(", ") + ".", affected: [{ url: result.url, detail: poor.join(", ") + " (" + result.field.scope + "-level field data)" }], evidence: ["Field (real users, 28 days): " + poor.join(", "), "Lab performance score: " + (result.lab.score ?? "n/a")], factors: result.opportunities.slice(0, 3).map(o => o.title), implication: "Slow experiences reduce conversion and can affect rankings through page experience signals.", recommendation: "Address the largest lab opportunities first: " + (result.opportunities.slice(0, 3).map(o => o.title).join("; ") || "reduce server response and script cost") + ".", effort: "high", impact: 4, metric: "CrUX 75th percentile LCP ≤ 2.5 s, INP ≤ 200 ms, CLS ≤ 0.1.", evidenceClass: "third-party", source: "Google PageSpeed Insights (CrUX field data + Lighthouse lab)", methodology: "Field data are Chrome users' 75th percentiles over 28 days; lab data are a single simulated Lighthouse run.", confidence: "high" });
    else if (result.lab.score !== null && result.lab.score < 50) drafts.push({ rule: "lab-performance:" + result.url, module: "performance", title: "Lab performance score is low on mobile (" + result.lab.score + "/100)", severity: "medium", summary: "Lighthouse lab test indicates slow loading; no poor field data was reported.", affected: [{ url: result.url, detail: "Lab LCP " + Math.round((result.lab.lcpMs || 0) / 100) / 10 + " s · TBT " + Math.round(result.lab.tbtMs || 0) + " ms" }], evidence: result.opportunities.slice(0, 4).map(o => o.title + " (≈" + o.savingsMs + " ms)"), factors: result.opportunities.slice(0, 3).map(o => o.title), implication: "Simulated slow-device performance suggests risk to user experience; confirm with field data.", recommendation: "Prioritise the listed lab opportunities.", effort: "medium", impact: 3, metric: "Lab score and field LCP/INP.", evidenceClass: "third-party", source: "Google PageSpeed Insights (Lighthouse lab)", methodology: "Single simulated mobile Lighthouse run.", confidence: "medium" });
  }

  // Content and GEO readiness.
  const readiness = content.map(p => ({ p, ...geoReadiness(p) }));
  const lowReadiness = readiness.filter(r => r.score < 50);
  if (readiness.length && lowReadiness.length > readiness.length * 0.4) drafts.push({ rule: "geo-readiness", module: "geo", title: "Most content is not structured for AI answers", severity: "medium", summary: lowReadiness.length + " of " + readiness.length + " content pages meet fewer than half of the GEO readiness criteria.", affected: lowReadiness.slice(0, 25).map(r => ({ url: r.p.finalUrl, detail: r.score + "/100 · missing: " + r.criteria.filter(c => !c.met).map(c => c.name).slice(0, 3).join(", ") })), affectedCount: lowReadiness.length, evidence: ["Average readiness: " + Math.round(readiness.reduce((s, r) => s + r.score, 0) / readiness.length) + "/100"], factors: ["Content written for brochures rather than questions.", "Missing structured data and authorship."], implication: "Generative search systems favour clear, attributable, well-structured answers; unstructured pages are less likely to be cited.", recommendation: "Restructure priority pages around real questions with direct answers, lists, data, dates, authorship and schema.", effort: "medium", impact: 4, metric: "GEO readiness score; AI citation rate in repeated samples.", confidence: "medium", methodology: "Eight transparent page criteria of equal weight. This is a readiness heuristic, not a measure of AI visibility." });

  // Competitive gaps.
  if (competitors.length && pages.length) {
    const ownSchema = pages.filter(p => p.schema.types.length).length / pages.length;
    const ownWords = median(content.map(p => p.content.words));
    const ahead = competitors.filter(c => c.pages.length && (median(c.pages.map(p => p.content.words)) > ownWords * 1.4 || c.pages.filter(p => p.schema.types.length).length / c.pages.length > ownSchema + 0.3));
    if (ahead.length) drafts.push({ rule: "competitor-depth", module: "competitive", title: ahead.length + " competitors publish deeper or better-structured pages", severity: "medium", summary: "Compared on equally sampled pages, competitors show more content depth or structured data coverage.", affected: ahead.map(c => ({ url: c.website, detail: "Median words " + median(c.pages.map(p => p.content.words)) + " vs " + ownWords + "; schema coverage " + share(c.pages.filter(p => p.schema.types.length).length, c.pages.length) + " vs " + Math.round(ownSchema * 100) + "%" })), evidence: ["Competitor samples: " + competitors.map(c => c.name + " (" + c.pages.length + " pages)").join(", ")], factors: ["Competitors investing in content and technical markup."], implication: "Search engines and AI systems have richer material to rank and cite from competitors.", recommendation: "Close the depth and markup gap on the pages that map to shared commercial topics.", effort: "high", impact: 3, metric: "Relative content depth and schema coverage on matched templates.", confidence: "low", methodology: "Small sample of competitor pages (home and linked pages). Indicative only." });
  }

  // First-party search evidence.
  if (firstParty.gsc?.rows.length) {
    const rows = firstParty.gsc.rows;
    const avgCtr = rows.reduce((s, r) => s + r.clicks, 0) / Math.max(1, rows.reduce((s, r) => s + r.impressions, 0));
    const opp = rows.filter(r => r.impressions >= 100 && r.ctr < avgCtr * 0.6 && r.position <= 15).sort((a, b) => b.impressions - a.impressions);
    if (opp.length) drafts.push({ rule: "gsc-low-ctr", module: "search", title: opp.length + " high-impression queries with below-average CTR", severity: "medium", summary: "Queries are seen often but clicked rarely relative to the property's average CTR.", affected: opp.slice(0, 20).map(r => ({ url: brief.website, detail: "\"" + r.query + "\": " + r.impressions + " impr · CTR " + (r.ctr * 100).toFixed(1) + "% · pos " + r.position.toFixed(1) })), evidence: ["Property average CTR across returned queries: " + (avgCtr * 100).toFixed(1) + "%", firstParty.gsc.scope], factors: ["Snippets (title/description) not matching intent.", "SERP features absorbing clicks."], implication: "Improving snippets on high-visibility queries can lift traffic without new rankings.", recommendation: "Rewrite titles and descriptions for these queries and test structured data eligibility.", effort: "low", impact: 3, metric: "CTR for the listed queries over the next 28 days.", evidenceClass: "first-party", source: "Google Search Console (authorised)", confidence: "high", methodology: "Queries with ≥ 100 impressions, position ≤ 15 and CTR < 60% of the returned average." });
  }

  return drafts.map(d => ({ ...d, title: singular(d.title) })).map(d => ({
    id: d.rule,
    evidenceId: evidenceId(projectId, d.rule),
    rule: d.rule.split(":")[0],
    module: d.module,
    engine: moduleEngine[d.module],
    title: d.title,
    severity: d.severity,
    confidence: d.confidence || "high",
    evidenceClass: d.evidenceClass || "observed",
    summary: d.summary,
    affected: d.affected,
    affectedCount: d.affectedCount ?? d.affected.length,
    evidence: d.evidence,
    factors: d.factors,
    implication: d.implication,
    recommendation: d.recommendation,
    effort: d.effort,
    impact: d.impact,
    metric: d.metric,
    source: d.source || crawlSource,
    collectedAt,
    methodology: d.methodology || crawlMethod,
    limitations: d.limitations || crawlLimits,
  })).sort((a, b) => severityRank[a.severity] - severityRank[b.severity] || b.impact - a.impact || b.affectedCount - a.affectedCount);
}

export const severityRank: Record<Severity, number> = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };

export function median(values: number[]): number {
  if (!values.length) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : Math.round((sorted[mid - 1] + sorted[mid]) / 2);
}

/** "1 pages are" → "1 page is": generated titles read correctly for a count of one. */
export function singular(title: string): string {
  const m = /^1 (\S+ )?(pages|links|keywords|titles|URLs|articles|images|pairs|chains|loops|issues|competitors|queries|descriptions|sitemap URLs|internally linked URLs)\b/.exec(title);
  if (!m) return title;
  const nouns: Record<string, string> = { pages: "page", links: "link", keywords: "keyword", titles: "title", URLs: "URL", articles: "article", images: "image", pairs: "pair", chains: "chain", loops: "loop", issues: "issue", competitors: "competitor", queries: "query", descriptions: "description" };
  const verbs: [RegExp, string][] = [[/\bare\b/, "is"], [/\bhave\b/, "has"], [/\black\b/, "lacks"], [/\bshare\b/, "shares"], [/\bshow\b/, "shows"], [/\bpoint\b/, "points"], [/\bconflict\b/, "conflicts"], [/\bskip\b/, "skips"], [/\bcarry\b/, "carries"], [/\bload\b/, "loads"], [/\bpublish\b/, "publishes"]];
  let out = title.replace(/^(1 (?:\S+ )?)(pages|links|keywords|titles|URLs|articles|images|pairs|chains|loops|issues|competitors|queries|descriptions)\b/, (_, a, noun) => a + (nouns[noun] || noun));
  for (const [re, v] of verbs) if (re.test(out)) { out = out.replace(re, v); break; }
  return out;
}
